SELECT a.status, CASE WHEN a.balance >= 61000 THEN 'high' WHEN a.balance >= 17000 THEN 'mid' ELSE 'low' END AS balance_bucket, COUNT(CASE WHEN t.merchant = 'Starbucks' THEN 1 END) AS starbucks_count, SORT_ARRAY(COLLECT_SET(t.txn_type)) AS txn_type_list FROM transactions t RIGHT JOIN accounts a ON t.account_id = a.id GROUP BY a.status, CASE WHEN a.balance >= 61000 THEN 'high' WHEN a.balance >= 17000 THEN 'mid' ELSE 'low' END;
